/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
zones=['.','com','net','edu','it','example.com','company.com','service.com','lab.net','tools.net','university.edu','campus.edu','unibo.it','comune.it','regione.it','shop.example.com','blog.example.com','dept.company.com','intranet.company.com','api.service.com','research.lab.net','ai.research.lab.net','data.research.lab.net','dev.lab.net','ci.tools.net','vpn.university.edu','courses.university.edu','portal.campus.edu','studenti.unibo.it','servizi.comune.it','dati.regione.it','org','io','gov','info','foundation.org','project.org','startup.io','platform.io','ministero.gov','news.info','archive.foundation.org','docs.project.org','api.startup.io','status.platform.io','open.ministero.gov','servizi.ministero.gov','local.news.info','media.news.info']
ips={i:re.search(r'inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/24',Path(f'pc{i}.startup').read_text()).group(1) for i in range(1,61)}
index={z:i for i,z in enumerate(zones,1)}
children={z:[] for z in zones}
for z in zones[1:]:
 parent=z.partition('.')[2] or '.'
 assert parent in index
 children[parent].append(z)
apex_indices=list(range(16,21))+list(range(22,32))+list(range(42,50))
mx={'company.com':7,'university.edu':11,'dept.company.com':18,'servizi.ministero.gov':47}
def ns(z): return 'ns.root.' if z=='.' else 'ns.'+z+'.'
for z,i in index.items():
 d=Path(f'pc{i}/etc/bind'); d.mkdir(parents=True,exist_ok=True)
 (d/'named.conf').write_text('options {\\n    directory \"/var/cache/bind\";\\n    listen-on { any; };\\n    listen-on-v6 { none; };\\n    recursion no;\\n    allow-query { any; };\\n    dnssec-validation no;\\n    empty-zones-enable no;\\n};\\nzone \"'+z+'\" { type primary; file \"/etc/bind/db.lab\"; };\\n')
 lines=['"'$TTL 300'"',f'@ IN SOA {ns(z)} hostmaster.{\"\" if z==\".\" else z+\".\"} ( 1 3600 600 604800 300 )',f'@ IN NS {ns(z)}',f'{ns(z)} IN A {ips[i]}']
 if i in apex_indices: lines.append(f'@ IN A {ips[i]}')
 if z in mx:
  lines.extend([f'@ IN MX 10 mail.{z}.',f'mail IN A {ips[mx[z]]}'])
 for child in children[z]:
  lines.extend([f'{child}. IN NS {ns(child)}',f'{ns(child)} IN A {ips[index[child]]}'])
 (d/'db.lab').write_text('\\n'.join(lines)+'\\n')
d=Path('pc50/etc/bind'); d.mkdir(parents=True,exist_ok=True)
(d/'named.conf').write_text('options {\\n    directory \"/var/cache/bind\";\\n    listen-on { any; };\\n    listen-on-v6 { none; };\\n    recursion yes;\\n    allow-query { any; };\\n    allow-recursion { 10.16.0.0/16; 127.0.0.1; };\\n    allow-query-cache { 10.16.0.0/16; 127.0.0.1; };\\n    dnssec-validation no;\\n    empty-zones-enable no;\\n};\\nzone \".\" { type hint; file \"/etc/bind/db.lab-root\"; };\\n')
(d/'db.lab-root').write_text(f'. 3600000 IN NS ns.root.\\nns.root. 3600000 IN A {ips[1]}\\n')
for i in range(1,61):
 p=Path(f'pc{i}.startup'); s=p.read_text(); s+='\\n# DNS del laboratorio.\\nprintf \"nameserver '+ips[50]+'\\\\n\" > /etc/resolv.conf\\n'
 if i<=50: s+='systemctl restart bind9\\n'
 p.write_text(s)
print('Configurate',len(zones),'zone; resolver pc50:',ips[50])
PY"

